package render

import (
	"encoding/json"
	"os"
	"strings"
	"testing"
)

// goldenCase holds the output of the WordPress originals for one input,
// generated by dev/golden/gen.php (make golden).
type goldenCase struct {
	Name      string `json:"name"`
	In        string `json:"in"`
	Autop     string `json:"autop"`
	Unautop   string `json:"unautop"`
	Texturize string `json:"texturize"`
	Smilies   string `json:"smilies"`
	Dangit    string `json:"dangit"`
	Excerpt   string `json:"excerpt"`
}

// wpShortcodes are the shortcodes registered in the reference WordPress.
var wpShortcodes = map[string]bool{
	"wp_caption": true, "caption": true, "gallery": true, "playlist": true, "audio": true,
	"video": true, "embed": true, "fotogalerie": true, "paypal-donation": true,
}

// goldenFiles are the committed generic corpus and, if present, golden
// data generated from the locally imported site (make golden).
var goldenFiles = []string{"testdata/golden.json", "../../local/golden-site.json"}

func loadGolden(t *testing.T) []goldenCase {
	t.Helper()
	var cases []goldenCase
	for i, f := range goldenFiles {
		raw, err := os.ReadFile(f)
		if err != nil {
			if i == 0 {
				t.Fatal(err)
			}
			continue
		}
		var c []goldenCase
		if err := json.Unmarshal(raw, &c); err != nil {
			t.Fatalf("%s: %v", f, err)
		}
		cases = append(cases, c...)
	}
	return cases
}

func runGolden(t *testing.T, field string, fn func(goldenCase) (got, want string)) {
	t.Helper()
	failed := 0
	for _, c := range loadGolden(t) {
		got, want := fn(c)
		if got != want {
			failed++
			if failed <= 5 {
				t.Errorf("%s %s mismatch\n--- got\n%q\n--- want\n%q", field, c.Name, got, want)
			}
		}
	}
	if failed > 0 {
		t.Errorf("%s: %d cases differ", field, failed)
	}
}

func TestGoldenAutop(t *testing.T) {
	runGolden(t, "autop", func(c goldenCase) (string, string) { return Autop(c.In), c.Autop })
}

func TestGoldenShortcodeUnautop(t *testing.T) {
	runGolden(t, "unautop", func(c goldenCase) (string, string) {
		return ShortcodeUnautop(Autop(c.In), wpShortcodes), c.Unautop
	})
}

func TestGoldenTexturize(t *testing.T) {
	runGolden(t, "texturize", func(c goldenCase) (string, string) { return Texturize(c.In, wpShortcodes), c.Texturize })
}

func TestGoldenSmilies(t *testing.T) {
	runGolden(t, "smilies", func(c goldenCase) (string, string) { return ConvertSmilies(c.In), c.Smilies })
}

func TestGoldenDangit(t *testing.T) {
	runGolden(t, "dangit", func(c goldenCase) (string, string) { return CapitalPDangit(c.In), c.Dangit })
}

func TestGoldenExcerptWords(t *testing.T) {
	reg := map[string]ShortcodeFunc{}
	for k := range wpShortcodes {
		reg[k] = func(*Env, *Shortcode) string { return "" }
	}
	// excerpt_remove_blocks() drops some block types (e.g. lists) from
	// excerpts; block markup is gone after import, so only classic content
	// is comparable.
	runGolden(t, "excerpt", func(c goldenCase) (string, string) {
		if strings.Contains(c.In, "<!-- wp:") {
			return "", ""
		}
		return TrimWords(StripShortcodes(c.In, reg), 55, ExcerptMore), c.Excerpt
	})
}
